import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readdirSync, readFileSync, appendFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
const BOT = process.argv[2];
const { recordUnsubscribe, recordResubscribe, mayEmail } = await import(BOT);
process.env.STATE_DIR = mkdtempSync('/tmp/state-');
const D = (s) => new Date(s);
const mkt = (to) => ({ to, kind: 'marketing' });
const tx = (to) => ({ to, kind: 'transactional' });
const NOW = D('2026-10-22T12:00:00Z');
let n = 0; const ok = (name) => console.log('ok', ++n, name);

// 1. fresh address: marketing allowed
assert.deepEqual(await mayEmail(mkt('<EMAIL>'), NOW), { allowed: true, reason: null }); ok('fresh allowed');

// 2. unsubscribe blocks marketing, not transactional
await recordUnsubscribe('Jane@Example.com', D('2026-10-20T10:00:00Z'));
assert.deepEqual(await mayEmail(mkt('jane@example.com'), NOW), { allowed: false, reason: 'unsubscribed' }); ok('unsub blocks marketing, case-insensitive');
assert.deepEqual(await mayEmail(tx('jane@example.com'), NOW), { allowed: true, reason: null }); ok('unsub does not block transactional');

// 3. header forms, aliases, gmail dots
await recordUnsubscribe('"Jane D." <<EMAIL>>', D('2026-10-20T10:00:00Z'));
for (const a of ['<EMAIL>', '<EMAIL>', 'mailto:<EMAIL>', ' <<EMAIL>> ']) {
  const r = await mayEmail(mkt(a), NOW);
  assert.equal(r.reason, 'unsubscribed', a); }
ok('header/alias/gmail normalization');

// 4. out of order: resubscribe after unsub lifts it; late unsub that is older does not re-block
await recordResubscribe('jane@example.com', D('2026-10-21T10:00:00Z'));
assert.equal((await mayEmail(mkt('jane@example.com'), NOW)).allowed, true); ok('resub after unsub lifts');
await recordUnsubscribe('jane@example.com', D('2026-10-20T09:00:00Z')); // late, older
assert.equal((await mayEmail(mkt('jane@example.com'), NOW)).allowed, true); ok('late older unsub does not re-block');

// 5. newer unsub after resub blocks again
await recordUnsubscribe('jane@example.com', D('2026-10-22T08:00:00Z'));
assert.equal((await mayEmail(mkt('jane@example.com'), NOW)).reason, 'unsubscribed'); ok('newer unsub re-blocks');

// 6. resub stamped in future (clock skew) not yet effective
await recordResubscribe('<EMAIL>', D('2026-10-20T10:00:00Z'));
await recordUnsubscribe('<EMAIL>', D('2026-10-19T10:00:00Z'));
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).allowed, true);
await recordResubscribe('<EMAIL>', D('2026-10-25T10:00:00Z'));
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).allowed, true, 'older resub already fine');
await recordUnsubscribe('<EMAIL>', D('2026-10-23T10:00:00Z'));
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).reason, 'unsubscribed', 'future resub not yet in effect');
assert.equal((await mayEmail(mkt('<EMAIL>'), D('2026-10-26T00:00:00Z'))).allowed, true, 'effective later');
ok('future-dated resubscribe handling');

// 7. torn write at end of file is skipped and next record is not lost
const f = readdirSync(path.join(process.env.STATE_DIR, 'suppression'), { recursive: true }).find(p => p.endsWith('.jsonl') && 0 === 0);
const files = []; (function walk(d){ for (const e of readdirSync(d,{withFileTypes:true})) { const p=path.join(d,e.name); e.isDirectory()?walk(p):files.push(p);} })(path.join(process.env.STATE_DIR,'suppression'));
const target = files.find(p => readFileSync(p,'utf8').includes('"email":"<EMAIL>"')) ?? null;
await recordUnsubscribe('<EMAIL>', D('2026-10-20T10:00:00Z'));
const cf = (function(){ let found; (function walk(d){ for (const e of readdirSync(d,{withFileTypes:true})) { const p=path.join(d,e.name); if(e.isDirectory()) walk(p); else if (readFileSync(p,'utf8').includes('<EMAIL>')) found=p; } })(path.join(process.env.STATE_DIR,'suppression')); return found; })();
appendFileSync(cf, '\n{"v":1,"type":"unsub'); // crash mid-write
await recordResubscribe('<EMAIL>', D('2026-10-21T10:00:00Z'));
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).allowed, true); ok('torn line tolerated, later record kept');

// 8. invalid inputs
assert.equal((await mayEmail(mkt('not-an-email'), NOW)).reason, 'invalid_recipient');
assert.equal((await mayEmail({ to: '<EMAIL>', kind: 'newsletter' }), NOW).reason, 'unknown_message_kind');
await assert.rejects(recordUnsubscribe('<EMAIL>', '2026-10-20'));
await assert.rejects(recordUnsubscribe('<EMAIL>'));
await assert.rejects(recordUnsubscribe('a, <EMAIL>', NOW));
ok('invalid inputs');

// 9. concurrent writers from separate processes, all events survive
const dir = process.env.STATE_DIR;
const kids = [];
for (let i = 0; i < 8; i++) {
  kids.push(execFileSync(process.execPath, ['-e', `
    const b = await import(${JSON.stringify(BOT)});
    const at = new Date('2026-10-20T10:00:00Z');
    for (let j = 0; j < 25; j++) await b.recordUnsubscribe('<EMAIL>', at);
  `], { env: { ...process.env, STATE_DIR: dir }, input: '' }));
}
await Promise.all([]);
ok('spawned sequential workers (see below for parallel)');
EOF
