cat > "$T/test.mjs" <<'EOF'
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtempSync, readdirSync, readFileSync, appendFileSync } from 'node:fs';
import path from 'node:path';

const BOT = process.argv[2];
const STATE = mkdtempSync('/tmp/state-');
process.env.STATE_DIR = STATE;
const { recordUnsubscribe, recordResubscribe, mayEmail } = await import(BOT);

const D = (s) => new Date(s);
const mkt = (to) => ({ to, kind: 'marketing' });
const tx = (to) => ({ to, kind: 'transactional' });
const NOW = D('2026-10-22T12:00:00Z');
const isMarketingBlocked = async (to, now = NOW) => (await mayEmail(mkt(to), now)).reason === 'unsubscribed';
let n = 0;
const ok = (name) => console.log(`ok ${++n} ${name}`);

// 1 fresh address allowed
assert.deepEqual(await mayEmail(mkt('<EMAIL>'), NOW), { allowed: true, reason: null }); ok('fresh allowed');

// 2 unsubscribe blocks marketing only, case-insensitive
await recordUnsubscribe('Jane@Example.com', D('2026-10-20T10:00:00Z'));
assert.deepEqual(await mayEmail(mkt('jane@example.com'), NOW), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mayEmail(tx('jane@example.com'), NOW), { allowed: true, reason: null });
ok('unsubscribe blocks marketing, not transactional');

// 3 header forms and aliases map to the same person
await recordUnsubscribe('"Jane D." <<EMAIL>>', D('2026-10-20T10:00:00Z'));
for (const a of ['<EMAIL>', '<EMAIL>', 'mailto:<EMAIL>', ' <<EMAIL>> ']) {
  assert.equal(await isMarketingBlocked(a), true, a);
}
ok('header, alias and gmail normalization');

// 4 out of order: resubscribe lifts; an older late unsubscribe does not re-block
await recordResubscribe('jane@example.com', D('2026-10-21T10:00:00Z'));
assert.equal(await isMarketingBlocked('jane@example.com'), false);
await recordUnsubscribe('jane@example.com', D('2026-10-20T09:00:00Z'));
assert.equal(await isMarketingBlocked('jane@example.com'), false);
ok('resubscribe lifts; late older unsubscribe ignored');

// 5 newer unsubscribe after resubscribe blocks again
await recordUnsubscribe('jane@example.com', D('2026-10-22T08:00:00Z'));
assert.equal(await isMarketingBlocked('jane@example.com'), true);
ok('newer unsubscribe re-blocks');

// 6 resubscribe stamped after `now` is not yet effective
await recordUnsubscribe('<EMAIL>', D('2026-10-19T10:00:00Z'));
await recordResubscribe('<EMAIL>', D('2026-10-25T10:00:00Z'));
assert.equal(await isMarketingBlocked('<EMAIL>', NOW), true, 'future resub not effective');
assert.equal(await isMarketingBlocked('<EMAIL>', D('2026-10-26T00:00:00Z')), false, 'effective once now passes it');
ok('future-dated resubscribe');

// 7 torn line at end of ledger file: next record still kept
await recordUnsubscribe('<EMAIL>', D('2026-10-20T10:00:00Z'));
const files = [];
(function walk(d) { for (const e of readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); e.isDirectory() ? walk(p) : files.push(p); } })(path.join(STATE, 'suppression'));
const carl = files.find((p) => readFileSync(p, 'utf8').includes('"email":"<EMAIL>"'));
appendFileSync(carl, '\n{"v":1,"type":"unsub'); // simulated crash mid-write
await recordResubscribe('<EMAIL>', D('2026-10-21T10:00:00Z'));
assert.equal(await isMarketingBlocked('<EMAIL>'), false);
ok('torn line tolerated, later record kept');

// 8 invalid inputs
assert.equal((await mayEmail(mkt('not-an-email'), NOW)).reason, 'invalid_recipient');
assert.equal((await mayEmail({ to: '<EMAIL>', kind: 'newsletter' }), NOW).reason, 'unknown_message_kind');
await assert.rejects(recordUnsubscribe('<EMAIL>', '2026-10-20'));
await assert.rejects(recordUnsubscribe('<EMAIL>'));
await assert.rejects(recordUnsubscribe('a, <EMAIL>', NOW));
await assert.rejects(mayEmail(mkt('<EMAIL>'), '2026-10-20'));
ok('invalid inputs rejected or reported');

// 9 STATE_DIR unset -> marketing check throws, transactional does not need it
delete process.env.STATE_DIR;
await assert.rejects(mayEmail(mkt('<EMAIL>'), NOW), /STATE_DIR/);
assert.equal((await mayEmail(tx('<EMAIL>'), NOW)).allowed, true);
process.env.STATE_DIR = STATE;
ok('missing STATE_DIR fails loudly');

// 10 eight separate processes racing 25 unsubscribes each, plus resubscribes
const worker = `
  const b = await import(${JSON.stringify(BOT)});
  for (let j = 0; j < 25; j++) {
    await b.recordUnsubscribe('<EMAIL>', new Date('2026-10-20T10:00:00Z'));
    await b.recordResubscribe('<EMAIL>', new Date('2026-10-19T10:00:00Z'));
  }`;
const runs = Array.from({ length: 8 }, () => new Promise((res, rej) => {
  const c = spawn(process.execPath, ['--input-type=module', '-e', worker], { env: process.env, stdio: 'inherit' });
  c.on('exit', (code) => (code === 0 ? res() : rej(new Error(`worker exit ${code}`))));
}));
await Promise.all(runs);
const raceFile = files.length && (function find() { let f; (function walk(d) { for (const e of readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else if (readFileSync(p, 'utf8').includes('"email":"<EMAIL>"')) f = p; } })(path.join(STATE, 'suppression')); return f; })();
const lines = readFileSync(raceFile, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
assert.equal(lines.filter((l) => l.type === 'unsubscribe').length, 200, 'all unsubscribes written intact');
assert.equal(await isMarketingBlocked('<EMAIL>'), true);
ok('200 concurrent unsubscribes across 8 processes all intact');
console.log(`all ${n} checks passed`);
EOF
